1	"use client";
2	/* eslint-disable @next/next/no-img-element */
3	
4	import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
5	import {
6	  getHostingAccount,
7	  revealHostingSftpPassword,
8	  recheckHostingHealth,
9	  renameHostingAccount,
10	  listWebsites,
11	  listHostingDatabases,
12	  listHostingBackups,
13	  listHostingSubdomains,
14	  listHostingAddonDomains,
15	  listHostingTaskLog,
16	  installWordPress,
17	  installApp,
18	  listAppCatalog,
19	  setPrimaryHostingDomain,
20	  deleteSubdomain,
21	  deleteAddonDomain,
22	  createFreeSubdomainSite,
23	  createAddonDomain,
24	  checkHostingSubdomain,
25	  removeHostingThumbnail,
26	  attachDomainToWebsite,
27	  setWebsitePrimaryDomain,
28	  listAttachedDomains,
29	  type HostingAccountView,
30	  type HostingWebsiteView,
31	  type AttachedDomainView,
32	  type SiteTarget,
33	} from "@/lib/actions-hosting";
34	import { getHostingEmailPool } from "@/lib/hosting-email";
35	import { Badge, StatCard, StatusDot, ComingSoon, timeAgo } from "@/components/ui/primitives";
36	import { Icon, type IconName } from "@/components/ui/Icon";
37	import { AppLogo } from "@/components/ui/AppLogo";
38	import { AppCredentials } from "./AppCredentials";
39	import { FileManager } from "./FileManager";
40	import { Backups } from "./Backups";
41	import { DatabasesPanel } from "./DatabasesPanel";
42	import { PhpSwitcher } from "./PhpSwitcher";
43	import { SubdomainsPanel } from "./SubdomainsPanel";
44	import { AddonDomainsPanel } from "./AddonDomainsPanel";
45	import { CronPanel } from "./CronPanel";
46	import { EmailTab } from "./EmailTab";
47	import { HostingUpgradePanel } from "./HostingUpgradePanel";
48	
49	/* ==========================================================================
50	 * Hosting console — the WEBSITE-FIRST plan workspace, on the portal's real design
51	 * system (components/ui/primitives + Icon + AppLogo + the global .card/.btn utility
52	 * classes). NO emojis: every glyph is an inline-SVG <Icon> or a brand <AppLogo>.
53	 *
54	 * The model (logic + UI over the existing storage — no DB migration):
55	 *   HostingAccount = the PLAN (a capacity pool: sites, storage, mailbox pool, DBs).
56	 *   "Websites" (the primary site + each addon/independent-subdomain/legacy subdomain)
57	 *   are first-class PEERS. Nothing is "primary-centric": the account's original
58	 *   domain is simply the first website in the grid.
59	 *
60	 * Two URL-addressable views (links survive refresh):
61	 *   • PLAN CONSOLE — a left section-nav scoping the plan:
62	 *       Overview · Websites · Domains · Email · Databases · Backups · Activity · Settings
63	 *     URL: `?tab=<section>` (default overview).
64	 *   • WEBSITE PAGE — a self-contained per-site console with a simple sub-nav
65	 *       Overview · Site/App · Domain & SSL · Email · Backups
66	 *     and an Advanced drawer folding Files · Database · PHP · Cron · SSH/SFTP ·
67	 *     Staging · Logs.  URL: `?site=<id|primary>&stab=<subtab>`.
68	 *
69	 * Every read/mutation is a real ownership-guarded server action — no mock data.
70	 * ======================================================================== */
71	
72	/* Left section-nav for the plan (the screen map's §2 spine). */
73	const PLAN_SECTIONS: [key: string, label: string, icon: IconName][] = [
74	  ["overview", "Overview", "grid"],
75	  ["websites", "Websites", "globe"],
76	  ["domains", "Domains", "link"],
77	  ["email", "Email", "mail"],
78	  ["databases", "Databases", "database"],
79	  ["backups", "Backups", "clock"],
80	  ["activity", "Activity", "activity"],
81	  ["settings", "Settings", "settings"],
82	];
83	// Section keys that resolve to a panel (includes deep-link-only keys kept for
84	// back-compat with old URLs: `logs`→activity, plan-level `files`/`cron`).
85	const SECTION_KEYS = new Set([...PLAN_SECTIONS.map(([k]) => k), "logs", "files", "cron", "console"]);
86	
87	/* Website page — simple sub-nav (up front) + Advanced drawer (folded). */
88	const SITE_PRIMARY: [key: string, label: string][] = [
89	  ["overview", "Overview"],
90	  ["app", "Site / App"],
91	  ["domains", "Domain & SSL"],
92	  ["email", "Email"],
93	  ["backups", "Backups"],
94	];
95	const SITE_ADVANCED: [key: string, label: string, icon: IconName][] = [
96	  ["files", "Files", "folder"],
97	  ["site-db", "Database", "database"],
98	  ["php", "PHP", "cpu"],
99	  ["cron", "Cron", "clock"],
100	  ["ssh", "SSH / SFTP", "key"],
101	  ["staging", "Staging", "refresh"],
102	  ["logs", "Logs", "activity"],
103	];
104	const SITE_TAB_KEYS = new Set([...SITE_PRIMARY.map(([k]) => k), ...SITE_ADVANCED.map(([k]) => k)]);
105	const ADVANCED_KEYS = new Set(SITE_ADVANCED.map(([k]) => k));
106	
107	type Counts = {
108	  dbs: number;
109	  backups: number;
110	  emailUsed: number;
111	  emailCap: number | null;
112	  subs: number;
113	  addons: number;
114	};
115	
116	/* ---- app-visual mapping: an installed-app label → a brand logo or a clean icon --- */
117	
118	const APP_LOGO_MATCHERS: [needle: string, family: string][] = [
119	  ["woocommerce", "woocommerce"],
120	  ["wordpress", "wordpress"],
121	  ["ghost", "ghost"],
122	  ["nextcloud", "nextcloud"],
123	  ["gitea", "gitea"],
124	  ["grafana", "grafana"],
125	  ["jellyfin", "jellyfin"],
126	  ["portainer", "portainer"],
127	];
128	
129	function appVisual(installedApp: string | null): { logo?: string; icon: IconName } {
130	  const s = (installedApp ?? "").toLowerCase();
131	  if (!s) return { icon: "globe" }; // static site / no app
132	  for (const [needle, family] of APP_LOGO_MATCHERS) if (s.includes(needle)) return { logo: family, icon: "grid" };
133	  return { icon: "grid" };
134	}
135	
136	/** A square app badge: the real brand logo when known, else a tasteful icon chip. */
137	function AppBadge({ installedApp, size = 32 }: { installedApp: string | null; size?: number }) {
138	  const v = appVisual(installedApp);
139	  if (v.logo) return <AppLogo family={v.logo} name={installedApp ?? undefined} size={size} />;
140	  return (
141	    <span
142	      className="flex items-center justify-center rounded-lg border border-white/10 bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-200"
143	      style={{ width: size, height: size, minWidth: size }}
144	    >
145	      <Icon name={v.icon} size={Math.round(size * 0.52)} />
146	    </span>
147	  );
148	}
149	
150	/** A website's thumbnail: the customer's uploaded preview, or a branded placeholder
151	 *  (subtle gradient + app logo + hostname — never an emoji). */
152	function Thumbnail({ accountId, site }: { accountId: string; site: HostingWebsiteView }) {
153	  if (site.thumbnailAt) {
154	    const src = `/api/hosting/${accountId}/thumbnail?site=${encodeURIComponent(site.key)}&v=${encodeURIComponent(site.thumbnailAt)}`;
155	    return <img src={src} alt={`${site.hostname} preview`} className="h-full w-full object-cover" />;
156	  }
157	  return (
158	    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gradient-to-br from-navy-900 via-brand-500/10 to-accent-blue/20">
159	      <div
160	        className="absolute inset-0 opacity-[0.12]"
161	        style={{ backgroundImage: "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.6) 1px, transparent 0)", backgroundSize: "16px 16px" }}
162	      />
163	      <div className="relative flex flex-col items-center gap-2 px-3 text-center">
164	        <AppBadge installedApp={site.installedApp} size={40} />
165	        <span className="max-w-full truncate font-mono text-xs text-slate-300">{site.hostname}</span>
166	      </div>
167	    </div>
168	  );
169	}
170	
171	/* ============================================================== root shell === */
172	
173	export function HostingConsole({
174	  account,
175	  initialTab,
176	  initialPath,
177	  initialSite,
178	  initialSiteTab,
179	}: {
180	  account: HostingAccountView;
181	  initialTab?: string;
182	  initialPath?: string;
183	  initialSite?: string;
184	  initialSiteTab?: string;
185	}) {
186	  const normTab = (t?: string) =>
187	    !t || t === "console" ? "overview" : t === "logs" ? "activity" : SECTION_KEYS.has(t) ? t : "overview";
188	
189	  const [siteParam, setSiteParam] = useState<string | undefined>(initialSite);
190	  const [siteTab, setSiteTab] = useState<string>(
191	    initialSiteTab && SITE_TAB_KEYS.has(initialSiteTab) ? initialSiteTab : "overview",
192	  );
193	  const [section, setSection] = useState<string>(normTab(initialTab));
194	
195	  const active = account.status === "ACTIVE";
196	  const [sites, setSites] = useState<HostingWebsiteView[] | null>(null);
197	  const refreshSites = useCallback(() => {
198	    if (!active) { setSites([]); return; }
199	    listWebsites(account.id).then(setSites).catch(() => setSites([]));
200	  }, [account.id, active]);
201	  useEffect(() => { refreshSites(); }, [refreshSites]);
202	
203	  function pushUrl(params: Record<string, string | undefined>) {
204	    const qs = new URLSearchParams();
205	    for (const [k, v] of Object.entries(params)) if (v) qs.set(k, v);
206	    const s = qs.toString();
207	    window.history.replaceState(null, "", s ? `?${s}` : window.location.pathname);
208	  }
209	  const goSection = useCallback((sec: string) => {
210	    setSiteParam(undefined); setSection(sec); pushUrl(sec === "overview" ? {} : { tab: sec }); window.scrollTo(0, 0);
211	  }, []);
212	  const openSite = useCallback((param: string) => {
213	    setSiteParam(param); setSiteTab("overview"); pushUrl({ site: param, stab: "overview" }); window.scrollTo(0, 0);
214	  }, []);
215	  const goSiteTab = useCallback((t: string) => {
216	    setSiteTab(t); setSiteParam((p) => { pushUrl({ site: p, stab: t }); return p; });
217	  }, []);
218	  const goHub = useCallback(() => goSection("overview"), [goSection]);
219	
220	  if (siteParam) {
221	    return (
222	      <WebsiteDetail
223	        account={account}
224	        sites={sites}
225	        siteParam={siteParam}
226	        siteTab={siteTab}
227	        onHub={goHub}
228	        onSiteTab={goSiteTab}
229	        onSection={goSection}
230	        onSitesChanged={refreshSites}
231	      />
232	    );
233	  }
234	
235	  return (
236	    <PlanShell
237	      account={account}
238	      section={section}
239	      sites={sites}
240	      initialPath={initialPath}
241	      onSection={goSection}
242	      onOpenSite={openSite}
243	      onSitesChanged={refreshSites}
244	    />
245	  );
246	}
247	
248	/* ============================================================= plan header === */
249	
250	function ConsoleHeader({
251	  account,
252	  onAdd,
253	  onSection,
254	}: {
255	  account: HostingAccountView;
256	  onAdd?: () => void;
257	  onSection?: (s: string) => void;
258	}) {
259	  const [editing, setEditing] = useState(false);
260	  const [value, setValue] = useState(account.name ?? "");
261	  const [busy, setBusy] = useState(false);
262	  const [err, setErr] = useState("");
263	  const active = account.status === "ACTIVE";
264	
265	  async function save() {
266	    setBusy(true); setErr("");
267	    const r = await renameHostingAccount(account.id, value);
268	    setBusy(false);
269	    if (r.error) { setErr(r.error); return; }
270	    setEditing(false);
271	    window.location.reload();
272	  }
273	
274	  return (
275	    <div className="flex flex-wrap items-start justify-between gap-4">
276	      <div className="min-w-0 flex-1">
277	        <div className="flex flex-wrap items-center gap-3">
278	          {editing ? (
279	            <div className="flex flex-wrap items-center gap-2">
280	              <input
281	                className="input max-w-[280px] text-lg font-semibold"
282	                value={value}
283	                maxLength={60}
284	                autoFocus
285	                disabled={busy}
286	                placeholder={`My ${account.planName} workspace`}
287	                onChange={(e) => setValue(e.target.value)}
288	                onKeyDown={(e) => { if (e.key === "Enter") save(); if (e.key === "Escape") setEditing(false); }}
289	              />
290	              <button className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save"}</button>
291	              <button className="btn-secondary px-3 py-1.5 text-sm" disabled={busy} onClick={() => { setEditing(false); setValue(account.name ?? ""); }}>Cancel</button>
292	            </div>
293	          ) : (
294	            <>
295	              <h1 className="page-title">{account.displayName}</h1>
296	              <button
297	                type="button"
298	                title="Rename this plan"
299	                onClick={() => setEditing(true)}
300	                className="btn-ghost inline-flex h-8 w-8 items-center justify-center p-0 text-slate-400 hover:text-white"
301	              >
302	                <Icon name="pencil" size={15} />
303	              </button>
304	              <Badge tone="brand">{account.planName}</Badge>
305	              <StatusDot status={account.status} />
306	            </>
307	          )}
308	        </div>
309	        {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
310	        <div className="mt-2 flex flex-wrap items-center gap-2">
311	          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">All hosting</a>
312	        </div>
313	      </div>
314	
315	      {active && (onAdd || onSection) && (
316	        <div className="flex flex-wrap items-center gap-2">
317	          {onSection && (
318	            <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" onClick={() => onSection("settings")}>
319	              <Icon name="arrow-up" size={15} /> Upgrade
320	            </button>
321	          )}
322	          {onAdd && (
323	            <button className="btn-primary inline-flex items-center gap-1.5 text-sm" onClick={onAdd}>
324	              <Icon name="plus" size={15} /> Add website
325	            </button>
326	          )}
327	        </div>
328	      )}
329	    </div>
330	  );
331	}
332	
333	/* ============================================================== plan shell === */
334	
335	function PlanShell({
336	  account,
337	  section,
338	  sites,
339	  initialPath,
340	  onSection,
341	  onOpenSite,
342	  onSitesChanged,
343	}: {
344	  account: HostingAccountView;
345	  section: string;
346	  sites: HostingWebsiteView[] | null;
347	  initialPath?: string;
348	  onSection: (s: string) => void;
349	  onOpenSite: (param: string) => void;
350	  onSitesChanged: () => void;
351	}) {
352	  const active = account.status === "ACTIVE";
353	  const [adding, setAdding] = useState(false);
354	  const [counts, setCounts] = useState<Counts | null>(null);
355	
356	  useEffect(() => {
357	    if (!active) return;
358	    let live = true;
359	    Promise.all([
360	      listHostingDatabases(account.id).catch(() => []),
361	      listHostingBackups(account.id).catch(() => []),
362	      listHostingSubdomains(account.id).catch(() => []),
363	      listHostingAddonDomains(account.id).catch(() => []),
364	      getHostingEmailPool(account.id).catch(() => null),
365	    ]).then(([dbs, backups, subs, addons, email]) => {
366	      if (!live) return;
367	      setCounts({
368	        dbs: dbs.length,
369	        backups: backups.length,
370	        emailUsed: email?.poolUsed ?? 0,
371	        emailCap: email?.poolCap ?? null,
372	        subs: subs.filter((s) => s.status !== "DELETING").length,
373	        addons: addons.filter((d) => d.status !== "DELETING").length,
374	      });
375	    });
376	    return () => { live = false; };
377	  }, [account.id, active, sites]);
378	
379	  const add = () => setAdding(true);
380	
381	  let body: ReactNode;
382	  if (!active && section !== "settings") {
383	    body = <NotReady />;
384	  } else {
385	    switch (section) {
386	      case "overview":
387	        body = <OverviewSection account={account} sites={sites} counts={counts} onSection={onSection} onOpenSite={onOpenSite} onAdd={add} onSitesChanged={onSitesChanged} />;
388	        break;
389	      case "websites":
390	        body = <WebsitesSection account={account} sites={sites} onOpenSite={onOpenSite} onAdd={add} onSitesChanged={onSitesChanged} />;
391	        break;
392	      case "domains":
393	        body = <DomainsSection account={account} />;
394	        break;
395	      case "email":
396	        body = <EmailTab account={account} />;
397	        break;
398	      case "databases":
399	        body = <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} />;
400	        break;
401	      case "backups":
402	        body = <Backups accountId={account.id} />;
403	        break;
404	      case "activity":
405	      case "logs":
406	        body = <LogsPanel accountId={account.id} />;
407	        break;
408	      case "files":
409	        body = <FileManager accountId={account.id} initialPath={initialPath} />;
410	        break;
411	      case "cron":
412	        body = <CronPanel accountId={account.id} username={account.username} />;
413	        break;
414	      case "settings":
415	        body = <SettingsSection account={account} onSection={onSection} />;
416	        break;
417	      default:
418	        body = <OverviewSection account={account} sites={sites} counts={counts} onSection={onSection} onOpenSite={onOpenSite} onAdd={add} onSitesChanged={onSitesChanged} />;
419	    }
420	  }
421	
422	  return (
423	    <div>
424	      <ConsoleHeader account={account} onAdd={active ? add : undefined} onSection={active ? onSection : undefined} />
425	      <StatusBanner account={account} />
426	
427	      <div className="mt-6 grid grid-cols-1 gap-6 lg:grid-cols-[210px_1fr] lg:items-start">
428	        <SectionNav section={section} onSection={onSection} />
429	        <div className="min-w-0 animate-fade-up">{body}</div>
430	      </div>
431	
432	      {adding && (
433	        <AddWebsiteWizard
434	          account={account}
435	          onClose={() => setAdding(false)}
436	          onCreated={(openParam) => { setAdding(false); onSitesChanged(); if (openParam) onOpenSite(openParam); }}
437	        />
438	      )}
439	    </div>
440	  );
441	}
442	
443	function SectionNav({ section, onSection }: { section: string; onSection: (s: string) => void }) {
444	  const activeKey = section === "logs" ? "activity" : section === "console" ? "overview" : section;
445	  return (
446	    <nav className="flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md lg:sticky lg:top-4 lg:flex-col lg:overflow-visible">
447	      {PLAN_SECTIONS.map(([key, label, icon]) => {
448	        const on = activeKey === key;
449	        return (
450	          <button
451	            key={key}
452	            type="button"
453	            onClick={() => onSection(key)}
454	            className={`inline-flex items-center gap-2 whitespace-nowrap rounded-xl px-3 py-2 text-sm font-medium transition-colors lg:w-full ${
455	              on
456	                ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
457	                : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
458	            }`}
459	          >
460	            <Icon name={icon} size={16} /> {label}
461	          </button>
462	        );
463	      })}
464	    </nav>
465	  );
466	}
467	
468	/* ============================================================ overview sect === */
469	
470	/**
471	 * A quota fill bar that animates 0 → its value on mount (violet→cyan, ~750ms ease).
472	 * Respects prefers-reduced-motion: reduced-motion users get the final state with no
473	 * transition. A tiny floor keeps a non-zero value visible even near 0%.
474	 */
475	function UsageBar({ pct }: { pct: number }) {
476	  const target = pct <= 0 ? 0 : Math.max(4, Math.min(100, pct));
477	  const [w, setW] = useState(0);
478	  useEffect(() => {
479	    const reduce = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
480	    if (reduce) { setW(target); return; }
481	    const r = requestAnimationFrame(() => setW(target));
482	    return () => cancelAnimationFrame(r);
483	  }, [target]);
484	  const full = pct >= 100;
485	  return (
486	    <div className="mt-3 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]" role="progressbar" aria-valuenow={Math.round(pct)} aria-valuemin={0} aria-valuemax={100}>
487	      <div
488	        className={`h-full rounded-full bg-gradient-to-r transition-[width] duration-700 ease-out motion-reduce:transition-none ${full ? "from-amber-400 to-amber-300" : "from-brand-400 to-accent-cyan"}`}
489	        style={{ width: `${w}%` }}
490	      />
491	    </div>
492	  );
493	}
494	
495	/**
496	 * A resource stat-card that mirrors the shared StatCard styling but adds an animated
497	 * quota bar (when a quota is known) + an optional sub-line (e.g. the folded-in Inodes
498	 * count on Storage). Renders as a button when `onClick` is given so the whole card
499	 * stays a section-nav target, exactly like the plain StatCards around it.
500	 */
501	function QuotaStatCard({
502	  label, value, icon, used, total, sub, onClick,
503	}: {
504	  label: string; value: string; icon: ReactNode;
505	  used?: number | null; total?: number | null; sub?: string; onClick?: () => void;
506	}) {
507	  const pct = used != null && total != null && total > 0 ? Math.min(100, Math.round((used / total) * 100)) : null;
508	  const inner = (
509	    <div className="card card-hover flex h-full flex-col justify-between p-5 text-left">
510	      <div className="flex items-start justify-between">
511	        <div className="min-w-0">
512	          <p className="text-[13px] text-slate-400">{label}</p>
513	          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
514	        </div>
515	        <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
516	          {icon}
517	        </div>
518	      </div>
519	      {pct !== null ? <UsageBar pct={pct} /> : sub ? <div className="mt-3 h-1.5" /> : null}
520	      {sub && <p className="mt-1.5 text-[11px] text-slate-500">{sub}</p>}
521	    </div>
522	  );
523	  return onClick ? (
524	    <button type="button" onClick={onClick} className="block h-full w-full">{inner}</button>
525	  ) : inner;
526	}
527	
528	function OverviewSection({
529	  account, sites, counts, onSection, onOpenSite, onAdd, onSitesChanged,
530	}: {
531	  account: HostingAccountView;
532	  sites: HostingWebsiteView[] | null;
533	  counts: Counts | null;
534	  onSection: (s: string) => void;
535	  onOpenSite: (p: string) => void;
536	  onAdd: () => void;
537	  onSitesChanged: () => void;
538	}) {
539	  const siteCount = sites?.length ?? 0;
