204	            <CloudflareMark className="h-4 w-4 flex-none" />
205	            Connect Cloudflare
206	          </a>
207	          <p className="text-xs text-slate-400">
208	            Sign in at Cloudflare and approve access — we only ask to{" "}
209	            {status?.scopeSummary ?? "read your zones and edit DNS records"}, and we only touch the
210	            records you ask us to.
211	            {what ? ` We'll ${what} as soon as you're back.` : ""}
212	          </p>
213	        </>
214	      ) : (
215	        <p className="text-xs text-slate-400">
216	          Cloudflare sign-in isn&apos;t set up on this server yet — paste an API token below instead.
217	        </p>
218	      )}
219	
220	      <details className="group">
221	        <summary className="cursor-pointer text-xs text-slate-500 hover:text-slate-300">
222	          Advanced: paste an API token instead
223	        </summary>
224	        <div className="mt-2">
225	          <p className="text-xs text-slate-400">
226	            Create a token scoped to{" "}
227	            <span className="font-medium text-slate-200">Zone → DNS → Edit</span> (Cloudflare → My
228	            Profile → API Tokens → Create Token → Edit zone DNS). It&apos;s stored encrypted and used
229	            only to publish the records you ask for.
230	          </p>
231	          <div className="mt-2 flex flex-wrap items-end gap-2">
232	            <div className="min-w-0 flex-1">
233	              <label className="label">Cloudflare API token</label>
234	              <input
235	                className="input"
236	                type="password"
237	                value={token}
238	                onChange={(e) => setToken(e.target.value)}
239	                placeholder="Paste token"
240	                autoCapitalize="none"
241	                autoCorrect="off"
242	                spellCheck={false}
243	              />
244	            </div>
245	            <button className="btn-secondary py-1.5 text-sm" onClick={connectWithToken} disabled={saving}>
246	              {saving ? "Connecting…" : "Use token"}
247	            </button>
248	          </div>
249	        </div>
250	      </details>
251	    </div>
252	  );
253	}
