3	/**
4	 * Cloudflare as an ACCOUNT-LEVEL integration.
5	 *
6	 * The connection used to be email-only (a token pasted inside the Business Email
7	 * DNS panel). It is now a first-class integration surfaced in Settings and reused
8	 * by every DNS surface: mail records, "point this website at my server", and the
9	 * post-migration domain cutover.
10	 *
11	 * Preferred path is OAuth ("Connect Cloudflare" → consent → we hold short-lived
12	 * credentials with a refresh token). The legacy paste-an-API-token path is kept
13	 * as an advanced fallback and still works, including for anyone who connected
14	 * before OAuth existed — `readStoredCloudflare` sniffs which shape is stored.
15	 *
16	 * NO SCHEMA CHANGE: both shapes live encrypted in `User.cloudflareTokenEnc`.
17	 * The token/credentials are never logged, never returned to the client.
18	 */
19	
20	import { revalidatePath } from "next/cache";
21	import { db } from "./db";
22	import { requireUser } from "./auth";
23	import { checkRateLimit } from "./rate-limit";
24	import { encryptSecret } from "./crypto-box";
25	import { SANDBOX } from "./sandbox";
26	import { saveCloudflareToken } from "./actions-email-hosting";
27	import {
28	  CF_SCOPE_SUMMARY,
29	  cfRedirectUri,
30	  cfRevoke,
31	  cloudflareOauthConfigured,
32	  readStoredCloudflare,
33	} from "./cloudflare-oauth";
34	
35	type Result = { ok?: boolean; error?: string };
36	
37	export type CloudflareStatus = {
38	  /** Something usable is stored (OAuth credentials or a legacy API token). */
39	  connected: boolean;
40	  /** How they connected — drives the wording in Settings. */
41	  kind: "oauth" | "token" | null;
42	  /** Is the "Connect Cloudflare" button available in this environment? */
43	  oauthAvailable: boolean;
44	  /** Plain-English summary of the access we request. */
45	  scopeSummary: string;
46	};
47	
48	/**
49	 * Connection state for the current user. Safe to call from any surface — it
50	 * never returns the credentials themselves, only whether they exist.
51	 */
52	export async function getCloudflareStatus(): Promise<CloudflareStatus> {
53	  const user = await requireUser();
54	  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
55	  return {
56	    connected: stored !== null,
57	    kind: stored?.kind ?? null,
58	    // In sandbox the button works (synthetic connect) without registered creds.
59	    oauthAvailable: SANDBOX || cloudflareOauthConfigured(),
60	    scopeSummary: CF_SCOPE_SUMMARY,
61	  };
62	}
63	
64	/**
65	 * Advanced fallback: store a pasted Cloudflare API token. Delegates to the
66	 * existing verify-then-store path (`saveCloudflareToken`) so there is exactly one
67	 * implementation of "check the token is real before we keep it", then revalidates
68	 * the surfaces that show connection state.
69	 */
70	export async function connectCloudflareToken(token: string): Promise<Result> {
71	  // SANDBOX has no network, so Cloudflare's verify call can't run. Accept the
72	  // pasted value as-is (encrypted) so staging can exercise the whole flow.
73	  if (SANDBOX) {
74	    const user = await requireUser();
75	    const t = String(token ?? "").trim();
76	    if (t.length < 20 || t.length > 200) {
77	      return { error: "That doesn't look like a Cloudflare API token." };
78	    }
79	    const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
80	    if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
81	    await db.user.update({ where: { id: user.id }, data: { cloudflareTokenEnc: encryptSecret(t) } });
82	    revalidatePath("/dashboard/settings");
83	    return { ok: true };
84	  }
85	
86	  const res = await saveCloudflareToken(token);
87	  if (res.ok) revalidatePath("/dashboard/settings");
88	  return res;
89	}
90	
91	/**
92	 * Disconnect Cloudflare: clear the stored credentials. For an OAuth connection
93	 * we also make a best-effort revoke call at Cloudflare so their side drops too
94	 * (a failed remote revoke never blocks the local disconnect — clearing the blob
95	 * is what actually stops us using it).
96	 */
97	export async function disconnectCloudflare(): Promise<Result> {
98	  const user = await requireUser();
99	
100	  const rl = checkRateLimit(`cf-disconnect:${user.id}`, { max: 10, windowMs: 60_000 });
101	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
102	
103	  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
104	  if (!stored) return { ok: true };
105	
106	  if (stored.kind === "oauth") {
107	    await cfRevoke(stored.creds.refreshToken || stored.creds.accessToken);
108	  }
109	
110	  await db.user.update({ where: { id: user.id }, data: { cloudflareTokenEnc: null } });
111	  await db.auditLog.create({
112	    data: {
113	      userId: user.id,
114	      action: "cloudflare.disconnect",
115	      detail: stored.kind === "oauth" ? "OAuth connection revoked" : "API token removed",
116	    },
117	  });
118	
119	  revalidatePath("/dashboard/settings");
120	  revalidatePath("/dashboard/email");
121	  return { ok: true };
122	}
123	
124	/**
125	 * The exact redirect URI that must be registered on the Cloudflare OAuth client.
126	 * Surfaced in Settings only when OAuth isn't configured yet, so the operator can
127	 * see what to register. Contains no secrets.
128	 */
129	export async function cloudflareRedirectUri(): Promise<string> {
130	  await requireUser();
131	  return cfRedirectUri();
132	}
