export type SiteSpeedResult = { score?: number; lcpMs?: number; ttfbMs?: number; strategy?: string; error?: string };

/**
 * On-demand REAL performance test via Google PageSpeed Insights (Lighthouse; no API
 * key required). Two guarantees keep this honest and safe:
 *   1. It NEVER fabricates a number — it returns the real Lighthouse score or a plain
 *      error string the UI shows verbatim.
 *   2. It is NOT an open SSRF proxy — the caller passes a hostname, but we only test
 *      one this very account actually serves (primary + subdomains + addon domains +
 *      attached primary aliases), so a customer can't point it at an arbitrary URL.
 * No-ops in SANDBOX (no outbound network on staging). Owner or admin, rate-limited.
 */
export async function runSiteSpeedTest(accountId: string, hostname: string): Promise<SiteSpeedResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, status: true, primaryDomain: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The site isn’t active yet." };

  const host = String(hostname ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (!host || !/^[a-z0-9.-]+$/.test(host)) return { error: "Invalid host." };
  const [subs, addons, claims] = await Promise.all([
    db.hostingSubdomain.findMany({ where: { accountId }, select: { fqdn: true } }),
    db.hostingAddonDomain.findMany({ where: { accountId }, select: { domain: true } }),
    db.hostingHostnameClaim.findMany({ where: { accountId }, select: { hostname: true } }),
  ]);
  const owned = new Set<string>([
    a.primaryDomain.toLowerCase(),
    ...subs.map((s) => s.fqdn.toLowerCase()),
    ...addons.map((d) => d.domain.toLowerCase()),
    ...claims.map((c) => c.hostname.toLowerCase()),
  ]);
  if (!owned.has(host)) return { error: "That host isn’t on this account." };

  if (SANDBOX) return { error: "Speed test isn’t available in this environment." };

  const rl = checkRateLimit(`psi:${user.id}`, { max: 6, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many tests. Try again in ${rl.retryAfterSec}s.` };

  type PsiResult = {
    lighthouseResult?: {
      categories?: { performance?: { score?: number } };
      audits?: Record<string, { numericValue?: number } | undefined>;
    };
  };
  const api = `https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=${encodeURIComponent(`https://${host}`)}&category=performance&strategy=mobile`;
  try {
    const res = await fetch(api, { signal: AbortSignal.timeout(28_000) });
    if (!res.ok) return { error: `Speed test failed (HTTP ${res.status}). Make sure the site is reachable over HTTPS.` };
    const j = (await res.json()) as PsiResult;
    const score = j.lighthouseResult?.categories?.performance?.score;
    const audits = j.lighthouseResult?.audits ?? {};
    const lcp = audits["largest-contentful-paint"]?.numericValue;
    const ttfb = audits["server-response-time"]?.numericValue;
    if (typeof score !== "number") return { error: "Speed test returned no score — try again shortly." };
    return {
      score: Math.round(score * 100),
      lcpMs: typeof lcp === "number" ? Math.round(lcp) : undefined,
      ttfbMs: typeof ttfb === "number" ? Math.round(ttfb) : undefined,
      strategy: "mobile",
    };
  } catch {
    return { error: "Couldn’t reach the speed-test service. Try again in a moment." };
  }
}

