function bandwidthLabel(tb: number): string {
  if (!tb || tb <= 0) return "Metered";
  if (tb >= 1) return `${Number.isInteger(tb) ? tb : tb.toFixed(1)} TB/mo`;
  return `${Math.round(tb * 1000)} GB/mo`;
}

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  try { return new Date(iso).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" }); }
  catch { return "—"; }
}

/** Shared thumbnail upload/remove logic (header + anywhere the preview affordance lives). */
function useThumbUpload(account: HostingAccountView, site: HostingWebsiteView, onSitesChanged: () => void) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);
  async function upload(file: File) {
    setBusy(true); setErr("");
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch(`/api/hosting/${account.id}/thumbnail?site=${encodeURIComponent(site.key)}`, { method: "POST", body: fd });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) { setErr(j.error ?? "Upload failed."); return; }
      onSitesChanged();
    } catch { setErr("Upload failed."); }
    finally { setBusy(false); }
  }
  async function remove() {
    setBusy(true); setErr("");
    const r = await removeHostingThumbnail(account.id, site.key);
    setBusy(false);
    if (r.error) setErr(r.error); else onSitesChanged();
  }
  return { busy, err, fileRef, upload, remove };
}

/** A single compact metric in the header's resource strip. */
function HeaderStat({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="min-w-0">
      <p className="text-[10px] uppercase tracking-wide text-slate-500">{label}</p>
      <p className={`mt-0.5 truncate text-sm font-semibold text-slate-100 ${mono ? "font-mono" : ""}`}>{value}</p>
    </div>
  );
}

/** Small header thumbnail with the visit link + an upload/replace affordance overlaid. */
function HeaderThumb({ account, site, onSitesChanged }: { account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void }) {
  const { busy, err, fileRef, upload, remove } = useThumbUpload(account, site, onSitesChanged);
  return (
    <div className="shrink-0">
      <div className="group relative h-[62px] w-[104px] overflow-hidden rounded-lg border border-white/[0.08]">
        <a href={siteUrl(site)} target="_blank" rel="noreferrer" className="block h-full w-full" title={`Visit ${site.hostname}`}>
          <Thumbnail accountId={account.id} site={site} />
        </a>
        <button
          type="button"
          onClick={() => fileRef.current?.click()}
          disabled={busy}
          title={site.thumbnailAt ? "Replace thumbnail" : "Upload thumbnail"}
          className="absolute bottom-1 right-1 inline-flex h-6 w-6 items-center justify-center rounded-md bg-navy-900/85 text-slate-200 opacity-0 backdrop-blur transition-opacity hover:text-white group-hover:opacity-100 focus-visible:opacity-100"
        >
          <Icon name={busy ? "clock" : "upload"} size={13} />
        </button>
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          className="hidden"
          onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.currentTarget.value = ""; }}
        />
      </div>
      {site.thumbnailAt && (
        <button type="button" className="mt-1 text-[10px] text-slate-500 hover:text-slate-300" disabled={busy} onClick={remove}>Remove</button>
      )}
      {err && <p className="mt-1 max-w-[104px] text-[10px] text-red-400">{err}</p>}
    </div>
  );
}

/** The (⋯) header overflow menu — quick jumps into the site's tools. */
function HeaderMore({ site, onSiteTab }: { site: HostingWebsiteView; onSiteTab: (t: string) => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    function onDoc(e: MouseEvent) { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);
  return (
    <div className="relative" ref={ref}>
      <button type="button" className="btn-secondary inline-flex items-center px-2.5 py-1.5 text-sm" onClick={() => setOpen((o) => !o)} aria-label="More actions">
        <Icon name="more-horizontal" size={16} />
      </button>
      {open && (
        <div className="absolute right-0 top-full z-20 mt-1 w-52 overflow-hidden rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
          <MenuItem icon="folder" onClick={() => { setOpen(false); onSiteTab("files"); }}>File manager</MenuItem>
          <MenuItem icon="clock" onClick={() => { setOpen(false); onSiteTab("backups"); }}>Backups</MenuItem>
          <MenuItem icon="lock" onClick={() => { setOpen(false); onSiteTab("domains"); }}>Domain &amp; SSL</MenuItem>
          <MenuItem icon="mail" onClick={() => { setOpen(false); onSiteTab("email"); }}>Email</MenuItem>
          <MenuItem icon="wrench" onClick={() => { setOpen(false); onSiteTab("php"); }}>PHP &amp; advanced</MenuItem>
        </div>
      )}
    </div>
  );
}

/**
 * The website-page HEADER: a small thumbnail on the LEFT, then the hostname + status/
 * app/type badges, and on the right a compact REAL resource strip (storage %, bandwidth
 * allowance, backups, PHP) + WordPress Admin / View Site / (⋯). Everything here is real
 * account/site data — no invented metrics.
 */
function SiteHeader({
  account, site, onSiteTab, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSiteTab: (t: string) => void; onSitesChanged: () => void;
}) {
  const [backups, setBackups] = useState<number | null>(null);
  useEffect(() => { listHostingBackups(account.id).then((b) => setBackups(b.length)).catch(() => setBackups(null)); }, [account.id]);

  const url = siteUrl(site);
  const isWp = (site.installedApp ?? "").toLowerCase().includes("wordpress");
  const diskPct = account.diskUsedMB != null && account.diskQuotaMB > 0
    ? Math.min(100, Math.round((account.diskUsedMB / account.diskQuotaMB) * 100)) : null;
  const diskGB = Math.round(account.diskQuotaMB / 1024);

  return (
    <div className="card p-4 sm:p-5">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div className="flex min-w-0 items-center gap-4">
          <HeaderThumb account={account} site={site} onSitesChanged={onSitesChanged} />
          <div className="min-w-0">
            <div className="flex items-center gap-2">
              <AppBadge installedApp={site.installedApp} size={22} />
              <a href={url} target="_blank" rel="noreferrer" className="truncate font-mono text-lg font-semibold tracking-tight hover:underline" title={site.hostname}>
                {site.hostname}
              </a>
            </div>
            <div className="mt-1.5 flex flex-wrap items-center gap-1.5">
              {site.status === "ACTIVE" ? <Badge tone="green">Live</Badge> : <span><StatusDot status={site.status} /></span>}
              {site.sslActive ? <Badge tone="green">HTTPS</Badge> : <Badge tone="amber">HTTP</Badge>}
              <Badge tone="slate">{kindLabel(site)}</Badge>
              {site.installedApp && <Badge tone="brand">{site.installedApp}</Badge>}
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-3 lg:items-end">
          <div className="grid grid-cols-2 gap-x-6 gap-y-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-2.5 sm:grid-cols-4">
            <HeaderStat label="Storage" value={diskPct != null ? `${diskPct}% of ${diskGB}GB` : `${diskGB} GB`} />
            <HeaderStat label="Bandwidth" value={bandwidthLabel(account.bandwidthTB)} />
            <HeaderStat label="Backups" value={backups == null ? "—" : String(backups)} />
            <HeaderStat label="PHP" value={site.phpVersion} mono />
          </div>
          <div className="flex flex-wrap gap-2 lg:justify-end">
            {isWp && (
              <a href={`${url}/wp-admin/`} target="_blank" rel="noreferrer" className="btn-primary inline-flex items-center gap-1.5 text-sm">
                <AppLogo family="wordpress" size={16} /> WordPress Admin
              </a>
            )}
            <a href={url} target="_blank" rel="noreferrer" className="btn-secondary inline-flex items-center gap-1.5 text-sm">
              <Icon name="external-link" size={15} /> View site
            </a>
            <HeaderMore site={site} onSiteTab={onSiteTab} />
          </div>
        </div>
      </div>
    </div>
  );
}

