/* ----- per-site: thumbnail preview + upload/remove -------------------------- */

function SitePreviewCard({ account, site, onSitesChanged }: { account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);

  async function upload(file: File) {
    setBusy(true); setErr("");
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch(`/api/hosting/${account.id}/thumbnail?site=${encodeURIComponent(site.key)}`, { method: "POST", body: fd });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) { setErr(j.error ?? "Upload failed."); return; }
      onSitesChanged();
    } catch {
      setErr("Upload failed.");
    } finally {
      setBusy(false);
    }
  }
  async function remove() {
    setBusy(true); setErr("");
    const r = await removeHostingThumbnail(account.id, site.key);
    setBusy(false);
    if (r.error) setErr(r.error); else onSitesChanged();
  }

  return (
    <div className="card p-0">
      <div className="relative aspect-[16/9] w-full overflow-hidden rounded-t-2xl border-b border-white/[0.06]">
        <Thumbnail accountId={account.id} site={site} />
        <a
          href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`}
          target="_blank"
          rel="noreferrer"
          className="absolute right-2.5 top-2.5 inline-flex items-center gap-1 rounded-md bg-navy-900/80 px-2 py-1 text-xs text-slate-200 backdrop-blur hover:text-white"
        >
          Visit <Icon name="external-link" size={12} />
        </a>
      </div>
      <div className="flex flex-wrap items-center gap-2 p-3">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          className="hidden"
          onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.currentTarget.value = ""; }}
        />
        <button className="btn-secondary inline-flex items-center gap-1.5 text-xs" disabled={busy} onClick={() => fileRef.current?.click()}>
          <Icon name="upload" size={14} /> {busy ? "Uploading…" : site.thumbnailAt ? "Replace thumbnail" : "Upload thumbnail"}
        </button>
        {site.thumbnailAt && (
          <button className="btn-ghost inline-flex items-center gap-1.5 text-xs text-slate-400 hover:text-white" disabled={busy} onClick={remove}>
            <Icon name="trash" size={14} /> Remove
          </button>
        )}
      </div>
      {err && <p className="px-3 pb-3 text-xs text-red-400">{err}</p>}
    </div>
  );
}

function SiteOverviewTab({
  account, site, onSiteTab, onSection, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSiteTab: (t: string) => void; onSection: (s: string) => void; onSitesChanged: () => void;
}) {
  const rows = useTaskLog(account.id);
  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-[1.6fr_1fr] lg:items-start">
      <div className="space-y-6">
        <SitePreviewCard account={account} site={site} onSitesChanged={onSitesChanged} />

        <div className="card">
          <h3 className="mb-3 flex items-center gap-2 font-semibold">
            <AppBadge installedApp={site.installedApp} size={22} />
            {site.installedApp ? `${site.installedApp}` : "No app installed"}
          </h3>
          {site.installedApp ? (
            <p className="mb-3 text-sm text-slate-400">This website is running <span className="text-slate-200">{site.installedApp}</span>. Its admin login is under App credentials. Install a different app onto this site below.</p>
          ) : (
            <p className="mb-3 text-sm text-slate-400">Install WordPress in one click, pick another app from the catalog, or just upload your own files.</p>
          )}
          <SiteInstaller account={account} site={site} onSitesChanged={onSitesChanged} />
          {(site.installedApp ?? "").toLowerCase().includes("wordpress") && (
            <div className="mt-4 border-t border-white/[0.06] pt-4"><AppCredentials accountId={account.id} /></div>
          )}
        </div>

        <div className="card">
          <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="cpu" size={16} className="text-brand-300" /> Stats</h3>
          <dl className="space-y-2 text-sm">
            <Row k="Hostname" v={<span className="font-mono text-xs">{site.hostname}</span>} />
            <Row k="Type" v={kindLabel(site)} />
            <Row k="App" v={site.installedApp ?? "None"} />
            <Row k="PHP version" v={<span className="font-mono text-xs">{site.phpVersion}</span>} />
            <Row k="Document root" v={<span className="font-mono text-xs">{site.fileManagerPath}</span>} />
            <Row k="SSL" v={site.sslActive ? <span className="text-emerald-300">Active · auto-renew</span> : <span className="text-amber-300">Issuing</span>} />
          </dl>
        </div>

        <div className="card">
          <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="activity" size={16} className="text-brand-300" /> Recent activity</h3>
          {rows === null ? (
            <p className="text-sm text-slate-500">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-sm text-slate-500">No activity yet.</p>
          ) : (
            <ul className="space-y-0">
              {rows.slice(0, 5).map((t) => (
                <li key={t.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
                  <span className="min-w-0 flex-1 truncate text-slate-300">{LOG_LABELS[t.kind] ?? t.kind}</span>
                  <span className={`text-xs font-medium ${t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}`}>{t.status.toLowerCase()}</span>
                  <span className="shrink-0 text-xs text-slate-500">{timeAgo(new Date(t.createdAt))}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      <div className="card">
        <h3 className="mb-3 font-semibold">Quick actions</h3>
        <div className="flex flex-col gap-2">
          <QuickAction icon="grid" label="Install / manage app" onClick={() => onSiteTab("app")} />
          <QuickAction icon="lock" label="Domain & SSL" onClick={() => onSiteTab("domains")} />
          <QuickAction icon="mail" label="Email on this site" onClick={() => onSiteTab("email")} />
          <QuickAction icon="folder" label="File manager" onClick={() => onSiteTab("files")} />
          <QuickAction icon="clock" label="Backups" onClick={() => onSiteTab("backups")} />
          <QuickAction icon="database" label="Databases" onClick={() => onSection("databases")} />
          {(site.kind === "subdomain" || site.kind === "addon") && (
            <QuickAction icon="trash" label="Delete website" tone="danger" onClick={() => onSiteTab("domains")} />
          )}
        </div>
      </div>
    </div>
  );
}

