/* ----- per-site OVERVIEW: a dense, finished-product website dashboard ------- */

type SiteBackupRow = { id: string; sizeBytes: number; createdAt: string };

/** A small labeled value in the metadata strip. */
function MetaItem({ label, value, mono }: { label: string; value: ReactNode; mono?: boolean }) {
  return (
    <div className="min-w-0">
      <p className="text-[10px] uppercase tracking-wide text-slate-500">{label}</p>
      <p className={`mt-0.5 truncate text-sm text-slate-200 ${mono ? "font-mono text-xs" : ""}`}>{value}</p>
    </div>
  );
}

function SiteOverviewTab({
  account, site, onSiteTab, onSection, onSitesChanged,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSiteTab: (t: string) => void; onSection: (s: string) => void; onSitesChanged: () => void;
}) {
  const [backups, setBackups] = useState<SiteBackupRow[] | null>(null);
  const reloadBackups = useCallback(() => { listHostingBackups(account.id).then(setBackups).catch(() => setBackups([])); }, [account.id]);
  useEffect(() => { reloadBackups(); }, [reloadBackups]);

  const usedGB = account.diskUsedMB != null ? account.diskUsedMB / 1024 : null;
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  const usageSub = account.usageAt ? `Updated ${timeAgo(new Date(account.usageAt))}` : "Measuring…";
  const isWp = (site.installedApp ?? "").toLowerCase().includes("wordpress");

  return (
    <div className="space-y-6">
      {/* Metrics row — every value REAL. Storage carries the animated quota bar; Files
          (inodes), PHP and Bandwidth have no honest denominator so they show no bar. */}
      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
        <QuotaStatCard
          label="Storage"
          value={usedGB != null ? `${usedGB.toFixed(usedGB < 1 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`}
          icon={<Icon name="hard-drive" size={18} />}
          used={account.diskUsedMB}
          total={account.diskQuotaMB}
          sub={usageSub}
          onClick={() => onSection("settings")}
        />
        <QuotaStatCard
          label="Files (inodes)"
          value={account.inodesUsed != null ? account.inodesUsed.toLocaleString() : "—"}
          icon={<Icon name="file" size={18} />}
          sub={account.inodesUsed != null ? "inodes in use" : "Not measured yet"}
        />
        <QuotaStatCard
          label="PHP version"
          value={site.phpVersion}
          icon={<Icon name="cpu" size={18} />}
          sub="Plan-wide runtime"
          onClick={() => onSiteTab("php")}
        />
        <QuotaStatCard
          label="Bandwidth"
          value={bandwidthLabel(account.bandwidthTB)}
          icon={<Icon name="activity" size={18} />}
          sub="Included allowance"
        />
      </div>

      {/* Metadata strip — real docroot / server / dates. */}
      <div className="card">
        <div className="grid grid-cols-2 gap-x-6 gap-y-3 sm:grid-cols-4">
          <MetaItem label="Root directory" value={site.fileManagerPath} mono />
          <MetaItem label="Web server" value="nginx" />
          <MetaItem label="Created" value={fmtDate(account.provisionedAt ?? account.createdAt)} />
          <MetaItem label="Last updated" value={fmtDate(account.updatedAt)} />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-[1.6fr_1fr] lg:items-start">
        <div className="space-y-6">
          {/* App / WordPress */}
          <div className="card">
            <h3 className="mb-3 flex items-center gap-2 font-semibold">
              <AppBadge installedApp={site.installedApp} size={22} />
              {site.installedApp ? site.installedApp : "No app installed"}
              {isWp && (
                <a href={`${siteUrl(site)}/wp-admin/`} target="_blank" rel="noreferrer" className="ml-auto inline-flex items-center gap-1 text-xs font-semibold text-brand-300 hover:underline">
                  Open admin <Icon name="external-link" size={12} />
                </a>
              )}
            </h3>
            {site.installedApp ? (
              <p className="mb-3 text-sm text-slate-400">This website is running <span className="text-slate-200">{site.installedApp}</span>. Its admin login is below. You can also install a different app onto this site.</p>
            ) : (
              <p className="mb-3 text-sm text-slate-400">Install WordPress in one click, pick another app from the catalog, or just upload your own files.</p>
            )}
            <SiteInstaller account={account} site={site} onSitesChanged={onSitesChanged} />
            {isWp && (
              <div className="mt-4 border-t border-white/[0.06] pt-4"><AppCredentials accountId={account.id} /></div>
            )}
          </div>

          <SiteSecurityCard account={account} site={site} onSiteTab={onSiteTab} />
          <SitePerformanceCard account={account} site={site} />
          <SiteActivityCard accountId={account.id} onSiteTab={onSiteTab} />
        </div>

        <div className="space-y-6">
          {/* Quick actions */}
          <div className="card">
            <h3 className="mb-3 font-semibold">Quick actions</h3>
            <div className="flex flex-col gap-2">
              <QuickAction icon="grid" label="Install / manage app" onClick={() => onSiteTab("app")} />
              <QuickAction icon="folder" label="Open file manager" onClick={() => onSiteTab("files")} />
              <QuickAction icon="database" label="Manage databases" onClick={() => onSiteTab("site-db")} />
              <QuickAction icon="lock" label="Domain & SSL" onClick={() => onSiteTab("domains")} />
              <QuickAction icon="mail" label="Email on this site" onClick={() => onSiteTab("email")} />
              {(site.kind === "subdomain" || site.kind === "addon") && (
                <QuickAction icon="trash" label="Delete website" tone="danger" onClick={() => onSiteTab("domains")} />
              )}
            </div>
          </div>

          <SiteBackupsRailCard account={account} backups={backups} reload={reloadBackups} onSiteTab={onSiteTab} />
          <SiteDomainsRailCard account={account} site={site} onSiteTab={onSiteTab} />
          <NeedHelpCard />
        </div>
      </div>
    </div>
  );
}

/* ----- per-site overview cards --------------------------------------------- */

/** Security & SSL — every state comes from real per-site / serve-check data. */
function SiteSecurityCard({ account, site, onSiteTab }: { account: HostingAccountView; site: HostingWebsiteView; onSiteTab: (t: string) => void }) {
  const isPrimary = site.kind === "primary";
  // Reachability: prefer the account's real serve-verification (primary domain), else
  // the site's own lifecycle status. Never asserts "up" without a real signal.
  let reach: ReactNode;
  if (isPrimary && (account.serveHttpsOk != null || account.serveHttpOk != null || account.healthCheckedAt != null)) {
    reach = account.serveHttpsOk === true
      ? <span className="text-emerald-300">Responding over HTTPS</span>
      : account.serveHttpOk === true
        ? <span className="text-amber-300">Responding over HTTP</span>
        : <span className="text-amber-300">Not responding yet</span>;
  } else {
    reach = site.status === "ACTIVE"
      ? <span className="text-emerald-300">Live</span>
      : <StatusDot status={site.status} />;
  }
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="shield" size={16} className="text-brand-300" /> Security &amp; SSL</h3>
      <dl className="space-y-2 text-sm">
        <Row k="SSL certificate" v={site.sslActive ? <span className="text-emerald-300">Active · auto-renews</span> : <span className="text-amber-300">Issuing — automatic once DNS resolves</span>} />
        <Row k="Connection" v={site.sslActive ? <span className="text-emerald-300">HTTPS (encrypted)</span> : <span className="text-amber-300">HTTP — HTTPS pending</span>} />
        <Row k="Reachability" v={reach} />
        {isPrimary && account.healthNote && <Row k="Last health check" v={<span className="text-xs text-slate-400">{account.healthNote}</span>} />}
      </dl>
      <button className="btn-secondary mt-4 inline-flex items-center gap-1.5 text-sm" onClick={() => onSiteTab("domains")}>
        <Icon name="lock" size={15} /> Manage domain &amp; SSL
      </button>
    </div>
  );
}

/** Performance & CDN — REAL Cloudflare connect state + a REAL on-demand PageSpeed test. */
function SitePerformanceCard({ account, site }: { account: HostingAccountView; site: HostingWebsiteView }) {
  const [next, setNext] = useState("/dashboard/hosting");
  useEffect(() => { setNext(window.location.pathname + window.location.search); }, []);
  return (
    <div className="card">
      <h3 className="mb-1 flex items-center gap-2 font-semibold"><CloudflareMark className="h-4 w-4 flex-none" /> Performance &amp; CDN</h3>
      <p className="mb-3 text-sm text-slate-400">Put {site.hostname} behind Cloudflare&apos;s global CDN for faster loads and caching, and check its real speed anytime.</p>

      <CloudflareConnect intent="website" id={account.id} host={site.hostname} next={next} what="turn on the CDN for this site" compact>
        <div className="flex items-center gap-2 rounded-lg border border-emerald-500/25 bg-emerald-500/[0.06] px-3 py-2 text-sm text-emerald-300">
          <Icon name="check" size={16} /> CDN active via Cloudflare
        </div>
      </CloudflareConnect>

      <div className="mt-4 border-t border-white/[0.06] pt-4">
        <SpeedTest account={account} site={site} />
      </div>

      <div className="mt-4 flex items-center justify-between gap-2 border-t border-white/[0.06] pt-4">
        <div className="min-w-0">
          <p className="text-sm font-medium text-slate-200">Page caching</p>
          <p className="text-xs text-slate-500">Speed up repeat visits. Managed per-app (e.g. a WordPress cache plugin) or via Cloudflare.</p>
        </div>
        <Badge tone="slate">Set up in app</Badge>
      </div>
    </div>
  );
}

/** On-demand REAL Lighthouse score via Google PageSpeed Insights — never a fixed number. */
function SpeedTest({ account, site }: { account: HostingAccountView; site: HostingWebsiteView }) {
  const [res, setRes] = useState<SiteSpeedResult | null>(null);
  const [busy, setBusy] = useState(false);
  async function run() {
    setBusy(true); setRes(null);
    const r = await runSiteSpeedTest(account.id, site.hostname);
    setBusy(false); setRes(r);
  }
  const score = res?.score;
  const scoreTone = score == null ? "" : score >= 90 ? "text-emerald-300" : score >= 50 ? "text-amber-300" : "text-red-300";
  return (
    <div>
      <div className="flex items-center justify-between gap-2">
        <div className="min-w-0">
          <p className="text-sm font-medium text-slate-200">Speed test</p>
          <p className="text-xs text-slate-500">Google PageSpeed Insights · mobile</p>
        </div>
        <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" disabled={busy} onClick={run}>
          <Icon name="activity" size={15} /> {busy ? "Testing…" : "Run speed test"}
        </button>
      </div>
      {res?.error && <p className="mt-2 text-xs text-amber-300">{res.error}</p>}
      {score != null && (
        <div className="mt-3 flex flex-wrap items-center gap-4">
          <div className="flex items-baseline gap-1">
            <span className={`text-3xl font-bold tracking-tight ${scoreTone}`}>{score}</span>
            <span className="text-xs text-slate-500">/ 100</span>
          </div>
          <div className="flex gap-4 text-xs text-slate-400">
            {res?.lcpMs != null && <span>LCP <span className="font-mono text-slate-200">{(res.lcpMs / 1000).toFixed(1)}s</span></span>}
            {res?.ttfbMs != null && <span>TTFB <span className="font-mono text-slate-200">{res.ttfbMs}ms</span></span>}
          </div>
        </div>
      )}
    </div>
  );
}

/** Recent activity timeline (real task log), scoped to the plan. */
function SiteActivityCard({ accountId, onSiteTab }: { accountId: string; onSiteTab: (t: string) => void }) {
  const rows = useTaskLog(accountId);
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold">
        <Icon name="activity" size={16} className="text-brand-300" /> Recent activity
        <button type="button" onClick={() => onSiteTab("logs")} className="ml-auto text-xs font-semibold text-brand-300 hover:underline">View all</button>
      </h3>
      {rows === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : rows.length === 0 ? (
        <p className="text-sm text-slate-500">No activity yet.</p>
      ) : (
        <ul className="space-y-0">
          {rows.slice(0, 6).map((t) => (
            <li key={t.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
              <span className="min-w-0 flex-1 truncate text-slate-300">{LOG_LABELS[t.kind] ?? t.kind}</span>
              <span className={`text-xs font-medium ${t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}`}>{t.status.toLowerCase()}</span>
              <span className="shrink-0 text-xs text-slate-500">{timeAgo(new Date(t.createdAt))}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** Recent backups (real list) + Back up now. Backups cover the whole plan. */
function SiteBackupsRailCard({ account, backups, reload, onSiteTab }: { account: HostingAccountView; backups: SiteBackupRow[] | null; reload: () => void; onSiteTab: (t: string) => void }) {
  const [busy, setBusy] = useState(false);
  async function backupNow() {
    setBusy(true);
    const r = await createHostingBackup(account.id);
    setBusy(false);
    if (r.error) { alert(r.error); return; }
    setTimeout(reload, 1500);
  }
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold">
        <Icon name="clock" size={16} className="text-brand-300" /> Recent backups
        <button type="button" onClick={() => onSiteTab("backups")} className="ml-auto text-xs font-semibold text-brand-300 hover:underline">All backups</button>
      </h3>
      {backups === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : backups.length === 0 ? (
        <p className="text-sm text-slate-500">No backups yet — create your first below.</p>
      ) : (
        <ul className="space-y-0">
          {backups.slice(0, 3).map((b) => (
            <li key={b.id} className="flex items-center gap-3 border-t border-white/[0.06] py-2 text-sm first:border-t-0">
              <Icon name="clock" size={14} className="shrink-0 text-slate-500" />
              <span className="min-w-0 flex-1 truncate text-slate-300">{timeAgo(new Date(b.createdAt))}</span>
              <span className="shrink-0 text-xs text-slate-500">{fmtBytes(b.sizeBytes)}</span>
            </li>
          ))}
        </ul>
      )}
      <button className="btn-secondary mt-3 inline-flex w-full items-center justify-center gap-1.5 text-sm" disabled={busy} onClick={backupNow}>
        <Icon name="refresh" size={15} /> {busy ? "Starting…" : "Back up now"}
      </button>
    </div>
  );
}

/** Domain(s) on this website — primary + aliases (real), with a connect CTA. */
function SiteDomainsRailCard({ account, site, onSiteTab }: { account: HostingAccountView; site: HostingWebsiteView; onSiteTab: (t: string) => void }) {
  const [domains, setDomains] = useState<AttachedDomainView[] | null>(null);
  useEffect(() => {
    if (site.kind === "primary") {
      listAttachedDomains(account.id).then(setDomains).catch(() => setDomains([{ hostname: site.hostname, isPrimary: true }]));
    } else {
      setDomains([{ hostname: site.hostname, isPrimary: true }]);
    }
  }, [account.id, site.kind, site.hostname]);
  return (
    <div className="card">
      <h3 className="mb-3 flex items-center gap-2 font-semibold"><Icon name="globe" size={16} className="text-brand-300" /> Domains</h3>
      {domains === null ? (
        <p className="text-sm text-slate-500">Loading…</p>
      ) : (
        <ul className="space-y-2">
          {domains.map((d) => (
            <li key={d.hostname} className="flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
              <Icon name={d.isPrimary ? "star" : "link"} size={13} className="shrink-0 text-slate-500" />
              <a href={`https://${d.hostname}`} target="_blank" rel="noreferrer" className="min-w-0 flex-1 truncate font-mono text-xs text-slate-200 hover:underline">{d.hostname}</a>
              {d.isPrimary && <Badge tone="brand">Primary</Badge>}
            </li>
          ))}
        </ul>
      )}
      <button className="btn-secondary mt-3 inline-flex w-full items-center justify-center gap-1.5 text-sm" onClick={() => onSiteTab("domains")}>
        <Icon name="plus" size={15} /> Add / connect a domain
      </button>
    </div>
  );
}

/** Need help — honest links into real support surfaces. */
function NeedHelpCard() {
  return (
    <div className="card">
      <h3 className="mb-2 flex items-center gap-2 font-semibold"><Icon name="activity" size={16} className="text-brand-300" /> Need help?</h3>
      <p className="mb-3 text-sm text-slate-400">Stuck on DNS, SSL, or an app install? Our team can help.</p>
      <a href="/dashboard/support" className="btn-secondary inline-flex w-full items-center justify-center gap-1.5 text-sm">
        <Icon name="mail" size={15} /> Contact support
      </a>
    </div>
  );
}

